namespace docking.options.editor;





using docking.widgets.tree;
using ghidra.framework.options;

class OptionsRootTreeNode : OptionsTreeNode {
	private Options[] options;

	OptionsRootTreeNode(string name, Options[] options) : base(name, null)
    {
		this.options = options;

	}

	public OptionsRootTreeNode(Options options) : base(options)
    {
	}

	/* @Override */
	protected List<GTreeNode> generateChildren() {
		if (options == null) {
			return base.generateChildren();
		}
		List<GTreeNode> list = new List<GTreeNode>();
		foreach (Options option in options) {
			list.add(new OptionsTreeNode(option));
		}
		Collections.sort(list);
		return list;
	}

	// overridden because the root has no options to edit
	protected JComponent getEditorComponent() {
		return null;
	}
}
